//! Type-safe bitflag sets that can be freely combined and checked.
//!
//! Flags are represented by a newtype wrapper around an integer, so a flag set
//! cannot be accidentally mixed with a plain integer or with a different flag
//! type. Use the bitwise operators to build combinations and [`contains`] /
//! [`intersects`] to inspect them.
//!
//! ```
//! use typed_flags::Permissions;
//!
//! let perms = Permissions::READ | Permissions::WRITE;
//!
//! assert!(perms.contains(Permissions::READ));
//! assert!(perms.intersects(Permissions::WRITE));
//! assert!(!perms.contains(Permissions::EXECUTE));
//! ```
//!
//! [`contains`]: Permissions::contains
//! [`intersects`]: Permissions::intersects

use bitflags::bitflags;

bitflags! {
    /// A set of filesystem access rights.
    ///
    /// Individual rights can be combined with `|` and the resulting set can be
    /// queried with [`contains`](Permissions::contains),
    /// [`intersects`](Permissions::intersects), and the `has_*` helpers below.
    #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
    pub struct Permissions: u32 {
        /// Permission to read a resource.
        const READ    = 0b0000_0001;
        /// Permission to modify a resource.
        const WRITE   = 0b0000_0010;
        /// Permission to run a resource.
        const EXECUTE = 0b0000_0100;

        /// Read, write and execute.
        const ALL = Self::READ.bits()
            | Self::WRITE.bits()
            | Self::EXECUTE.bits();
    }
}

impl Permissions {
    /// An empty set, granting no access.
    pub const NONE: Self = Self::empty();

    /// Returns `true` if every flag in `other` is present in `self`.
    pub fn has_all(self, other: Self) -> bool {
        self.contains(other)
    }

    /// Returns `true` if at least one flag in `other` is present in `self`.
    pub fn has_any(self, other: Self) -> bool {
        self.intersects(other)
    }

    /// Returns a copy of `self` with the flags in `other` added.
    pub fn with(self, other: Self) -> Self {
        self | other
    }

    /// Returns a copy of `self` with the flags in `other` removed.
    pub fn without(self, other: Self) -> Self {
        self & !other
    }

    /// Returns a copy of `self` with the flags in `other` toggled.
    pub fn toggled(self, other: Self) -> Self {
        self ^ other
    }

    /// Returns `true` if no flags are set.
    pub fn is_none(self) -> bool {
        self.is_empty()
    }

    /// Returns `true` if all known flags are set.
    pub fn is_all(self) -> bool {
        self.contains(Self::ALL)
    }

    /// Total number of distinct flags in this set.
    pub fn len(self) -> u32 {
        self.bits().count_ones()
    }
}

#[cfg(test)]
mod tests {
    use super::Permissions;

    #[test]
    fn combines_with_bitwise_or() {
        let perms = Permissions::READ | Permissions::WRITE;
        assert_eq!(perms, Permissions::READ.with(Permissions::WRITE));
        assert_eq!(perms.len(), 2);
    }

    #[test]
    fn checks_membership() {
        let perms = Permissions::READ | Permissions::WRITE;
        assert!(perms.contains(Permissions::READ));
        assert!(perms.has_any(Permissions::WRITE | Permissions::EXECUTE));
        assert!(!perms.has_all(Permissions::ALL));
    }

    #[test]
    fn removes_and_toggles_flags() {
        let perms = Permissions::ALL.without(Permissions::EXECUTE);
        assert_eq!(perms, Permissions::READ | Permissions::WRITE);
        assert_eq!(perms.toggled(Permissions::EXECUTE), Permissions::ALL);
    }

    #[test]
    fn empty_and_full_sets() {
        assert!(Permissions::NONE.is_none());
        assert!(Permissions::ALL.is_all());
        assert!(!Permissions::READ.is_none());
        assert!(!Permissions::READ.is_all());
    }

    #[test]
    fn distinct_types_do_not_mix() {
        // The set is strongly typed: it is not a bare `u32`.
        let perms: Permissions = Permissions::READ;
        let bits: u32 = perms.bits();
        assert_eq!(bits, 1);
    }
}

