```rust
#[macro_export]
macro_rules! bitflags {
    (
        $(#[$outer:meta])*
        $vis:vis struct $Name:ident : $T:ty {
            $(
                $(#[$inner:meta])*
                const $Flag:ident = $value:expr;
            )*
        }
    ) => {
        $(#[$outer])*
        #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
        $vis struct $Name($T);

        impl $Name {
            $(
                $(#[$inner])*
                pub const $Flag: Self = Self($value);
            )*

            /// Returns the raw underlying bits.
            #[inline]
            pub const fn bits(self) -> $T {
                self.0
            }

            /// Creates a set from raw bits.
            #[inline]
            pub const fn from_bits(bits: $T) -> Self {
                Self(bits)
            }

            /// Creates a set from raw bits, returning `None` if any unknown bits are set.
            #[inline]
            pub const fn from_bits_checked(bits: $T) -> Option<Self> {
                let known: $T = 0 $(| Self::$Flag.0)*;
                if bits & !known == 0 { Some(Self(bits)) } else { None }
            }

            /// An empty set.
            #[inline]
            pub const fn empty() -> Self {
                Self(0)
            }

            /// Returns `true` if the set is empty.
            #[inline]
            pub const fn is_empty(self) -> bool {
                self.0 == 0
            }

            /// Returns `true` if `self` contains all flags in `other`.
            #[inline]
            pub const fn contains(self, other: Self) -> bool {
                self.0 & other.0 == other.0
            }

            /// Returns `true` if `self` and `other` share at least one flag.
            #[inline]
            pub const fn intersects(self, other: Self) -> bool {
                self.0 & other.0 != 0
            }

            /// Inserts the flags in `other`.
            #[inline]
            pub fn insert(&mut self, other: Self) {
                self.0 |= other.0;
            }

            /// Removes the flags in `other`.
            #[inline]
            pub fn remove(&mut self, other: Self) {
                self.0 &= !other.0;
            }

            /// Toggles the flags in `other`.
            #[inline]
            pub fn toggle(&mut self, other: Self) {
                self.0 ^= other.0;
            }

            /// Number of flags set.
            #[inline]
            pub const fn count_ones(self) -> u32 {
                self.0.count_ones()
            }
        }

