//! The [`bitflags!`] macro generates a newtype wrapper around an integer, so a
//! set of flags cannot be accidentally mixed with a plain integer or with a
//! different flag type. Combinations are built with the bitwise operators and
//! inspected with [`contains`](Permissions::contains) and
//! [`intersects`](Permissions::intersects).
//!
//! ```
//! use typed_flags::Permissions;
//!
//! let perms = Permissions::READ | Permissions::WRITE;
//!
//! assert!(perms.contains(Permissions::READ));
//! assert!(perms.intersects(Permissions::WRITE));
//! assert!(!perms.contains(Permissions::EXECUTE));
//! ```

/// Declares a strongly-typed bitflag set.
///
/// A single invocation defines a newtype over `$T` and one associated constant
/// per flag. The generated type implements `|`, `&`, `^`, `!`, the matching
/// assign operators, and the usual `contains` / `intersects` queries, so flag
/// sets stay type-safe and cannot be confused with raw integers.
///
/// ```
/// use typed_flags::bitflags;
///
/// bitflags! {
///     /// Which logging targets are enabled.
///     #[derive(Clone, Copy, PartialEq, Eq)]
///     pub struct LogLevel: u8 {
///         const ERROR = 0b001;
///         const WARN  = 0b010;
///         const INFO  = 0b100;
///     }
/// }
///
/// let level = LogLevel::ERROR | LogLevel::INFO;
/// assert!(level.contains(LogLevel::INFO));
/// assert_eq!(LogLevel::from_bits_checked(0b1000), None);
/// ```
///
/// Composite flags (a flag whose value is the union of others) are supported,
/// but the [`Debug`](core::fmt::Debug) implementation will list them alongside
/// their members. Prefer plain single-bit flags for readable output.
#[macro_export]
macro_rules! bitflags {
    (
        $(#[$outer:meta])*
        $vis:vis struct $Name:ident : $T:ty {
            $(
                $(#[$inner:meta])*
                const $Flag:ident = $value:expr;
            )*
        }
    ) => {
        $(#[$outer])*
        #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
        $vis struct $Name($T);

        impl $Name {
            $(
                $(#[$inner])*
                pub const $Flag: Self = Self($value);
            )*

            /// The empty set, with no flags set.
            #[inline]
            pub const fn empty() -> Self {
                Self(0)
            }

            /// A set containing every flag declared for this type.
            #[inline]
            pub const fn all() -> Self {
                Self(0 $(| Self::$Flag.0)*)
            }

            /// Returns the raw underlying bits.
            #[inline]
            pub const fn bits(self) -> $T {
                self.0
            }

            /// Builds a set directly from raw bits, keeping any unknown bits.
            #[inline]
            pub const fn from_bits(bits: $T) -> Self {
                Self(bits)
            }

            /// Builds a set from raw bits, returning `None` if `bits` contains
            /// any bit that is not part of a declared flag.
            #[inline]
            pub const fn from_bits_checked(bits: $T) -> ::core::option::Option<Self> {
                if bits & !Self::all().0 == 0 {
                    ::core::option::Option::Some(Self(bits))
                } else {
                    ::core::option::Option::None
                }
            }

            /// Returns `true` if no flags are set.
            #[inline]
            pub const fn is_empty(self) -> bool {
                self.0 == 0
            }

            /// Returns `true` if every flag in `other` is also set in `self`.
            #[inline]
            pub const fn contains(self, other: Self) -> bool {
                self.0 & other.0 == other.0
            }

            /// Returns `true` if `self` and `other` share at least one flag.
            #[inline]
            pub const fn intersects(self, other: Self) -> bool {
                self.0 & other.0 != 0
            }

            /// Adds every flag in `other` to `self`.
            #[inline]
            pub fn insert(&mut self, other: Self) {
                self.0 |= other.0;
            }

            /// Removes every flag in `other` from `self`.
            #[inline]
            pub fn remove(&mut self, other: Self) {
                self.0 &= !other.0;
            }

            /// Toggles every flag in `other` in `self`.
            #[inline]
            pub fn toggle(&mut self, other: Self) {
                self.0 ^= other.0;
            }

            /// The number of individual flags that are set.
            #[inline]
            pub const fn count_ones(self) -> u32 {
                self.0.count_ones()
            }
        }

        impl ::core::default::Default for $Name {
            #[inline]
            fn default() -> Self {
                Self::empty()
            }
        }

        impl ::core::ops::BitOr for $Name {
            type Output = Self;
            #[inline]
            fn bitor(self, rhs: Self) -> Self {
                Self(self.0 | rhs.0)
            }
        }

        impl ::core::ops::BitAnd for $Name {
            type Output = Self;
            #[inline]
            fn bitand(self, rhs: Self) -> Self {
                Self(self.0 & rhs.0)
            }
        }

        impl ::core::ops::BitXor for $Name {
            type Output = Self;
            #[inline]
            fn bitxor(self, rhs: Self) -> Self {
                Self(self.0 ^ rhs.0)
            }
        }

        impl ::core::ops::Not for $Name {
            type Output = Self;
            #[inline]
            fn not(self) -> Self {
                Self(!self.0)
            }
        }

        impl ::core::ops::BitOrAssign for $Name {
            #[inline]
            fn bitor_assign(&mut self, rhs: Self) {
                self.0 |= rhs.0;
            }
        }

        impl ::core::ops::BitAndAssign for $Name {
            #[inline]
            fn bitand_assign(&mut self, rhs: Self) {
                self.0 &= rhs.0;
            }
        }

        impl ::core::ops::BitXorAssign for $Name {
            #[inline]
            fn bitxor_assign(&mut self, rhs: Self) {
                self.0 ^= rhs.0;
            }
        }

        impl ::core::convert::From<$T> for $Name {
            #[inline]
            fn from(bits: $T) -> Self {
                Self(bits)
            }
        }

        impl ::core::convert::From<$Name> for $T {
            #[inline]
            fn from(flags: $Name) -> Self {
                flags.0
            }
        }

        impl ::core::fmt::Debug for $Name {
            fn fmt(
                &self,
                f: &mut ::core::fmt::Formatter<'_>,
            ) -> ::core::fmt::Result {
                let mut first = true;
                write!(f, "{}(", stringify!($Name))?;
                $(
                    if self.contains(Self::$Flag) {
                        if !first {
                            write!(f, " | ")?;
                        }
                        write!(f, "{}", stringify!($Flag))?;
                        first = false;
                    }
                )*
                if first {
                    write!(f, "NONE")?;
                }
                write!(f, ")")
            }
        }
    };
}

