    /// A set of filesystem access rights.
    #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
    pub struct Permissions: u32 {
        /// Permission to read a resource.
        const READ    = 0b0000_0001;
        /// Permission to modify a resource.
        const WRITE   = 0b0000_0010;
        /// Permission to run a resource.
        const EXECUTE = 0b0000_0100;
    }
}

impl Permissions {
    /// Read, write and execute.
    pub const ALL: Self = Self::READ.union(Self::WRITE).union(Self::EXECUTE);

    /// Returns a copy of `self` with the flags in `other` added.
    #[inline]
    pub const fn union(self, other: Self) -> Self {
        Self(self.bits() | other.bits())
    }

    /// Returns a copy of `self` with the flags in `other` removed.
    #[inline]
    pub const fn difference(self, other: Self) -> Self {
        Self(self.bits() & !other.bits())
    }

    /// Returns a copy of `self` with the flags in `other` toggled.
    #[inline]
    pub const fn symmetric_difference(self, other: Self) -> Self {
        Self(self.bits() ^ other.bits())
    }

    /// Returns `true` if every flag in `other` is present in `self`.
    #[inline]
    pub const fn has_all(self, other: Self) -> bool {
        self.contains(other)
    }

    /// Returns `true` if at least one flag in `other` is present in `self`.
    #[inline]
    pub const fn has_any(self, other: Self) -> bool {
        self.intersects(other)
    }

    /// Returns a copy of `self` with the flags in `other` added.
    #[inline]
    pub const fn with(self, other: Self) -> Self {
        self.union(other)
    }

    /// Returns a copy of `self` with the flags in `other` removed.
    #[inline]
    pub const fn without(self, other: Self) -> Self {
        self.difference(other)
    }
}

